        "testata": "Il Manifesto",
        "lingua_originale": "it",
        "titolo_orig": "Insulti e minacce ai lavoratori: i costi del consolato Usa",
        "testo_it": "Milano: commissariata per caporalato la Caddell, azienda subappaltatrice del nuovo consolato USA.",
        "priorita": "Bassa",
        "id_gruppo": 26,
        "link": "https://ilmanifesto.it/insulti-e-minacce-ai-lavoratori-i-costi-del-consolato-usa",
        "orario": "00:05",
